import requests, base64, time, statistics
# Timing test: does valid vs invalid user differ?
users = ["admin","root","user","test","guest","web","flag","a","b","c","x","y","z","administrator","dsv4","xben","054"]
results = {}
for u in users:
    b = base64.b64encode((u+":"+"wrongpass").encode()).decode()
    ts=[]
    for _ in range(5):
        t0=time.time()
        try:
            r=requests.get("http://web:80/", headers={"Authorization":"Basic "+b}, timeout=5)
        except Exception as e:
            ts.append(-1); continue
        ts.append((time.time()-t0)*1000)
    results[u] = (r.status_code, round(statistics.median(ts),1), round(min(ts),1), round(max(ts),1))
for u,(code,med,mn,mx) in sorted(results.items(), key=lambda kv: -kv[1][1]):
    print(f"{u:16s} code={code} median={med}ms min={mn}ms max={mx}ms")
